 * a `NotFoundError`.
 */
import { isArchived } from "@/lib/soft-delete";
import { assertOrgScope } from "@/lib/tenant";
import * as commentRepo from "@/server/repositories/comment-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as labelRepo from "@/server/repositories/label-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import { NotFoundError } from "./_support";
import type {
  CommentId,
  IssueId,
  LabelId,
  OrgId,
  ProjectId,
  UserId,
} from "@/types/common";
import type { Actor } from "@/types/member";

/** True when `userId` holds a live, active membership of `orgId`. */
export async function isCurrentMember(
  orgId: OrgId,
  userId: UserId,
): Promise<boolean> {
  const member = await memberRepo.findMember(orgId, userId);
  return member !== null && isCurrentMembership(member);
}

export function isCurrentMembership(member: {
  readonly status: string;
  readonly archivedAt: string | null;
}): boolean {
  return member.status === "active" && member.archivedAt === null;
}

/** Throws unless `userId` is a current member of the actor's organization. */
export async function assertCurrentMember(
  actor: Actor,
  userId: UserId,
  entity = "Member",
): Promise<void> {
  if (!(await isCurrentMember(actor.orgId, userId))) {
    throw new NotFoundError(entity, userId);
  }
}

/** Throws unless every label is one of the actor's organization's own. */
export async function assertLabelsUsable(
  actor: Actor,
  labelIds: readonly LabelId[],
): Promise<void> {
  if (labelIds.length === 0) return;

  const owners = await labelRepo.findLabelOwners(labelIds);
  for (const labelId of labelIds) {
    const owner = owners.get(labelId);
    if (owner !== undefined) assertOrgScope(actor, owner);
  }
  for (const labelId of labelIds) {
    if (!owners.has(labelId)) throw new NotFoundError("Label", labelId);
  }
}

/** Throws unless `parentId` is a live issue of `projectId` in the actor's org. */
export async function assertParentIssueUsable(
  actor: Actor,
  projectId: ProjectId,
  parentId: IssueId,
): Promise<void> {
  const parent = await issueRepo.findIssueAcrossOrgs(parentId);
  if (parent === null) throw new NotFoundError("Issue", parentId);
  assertOrgScope(actor, parent.orgId);
  if (isArchived(parent) || parent.projectId !== projectId) {
    throw new NotFoundError("Issue", parentId);
  }
}

/** Throws unless `parentId` is a live, top-level comment on `issueId`. */
export async function assertParentCommentUsable(
  actor: Actor,
  issueId: IssueId,
